WITH filtered AS (SELECT *, CEIL(pressure) AS pressure_whole FROM device_readings WHERE HOUR(reading_ts) BETWEEN 10 AND 16), with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_device_readings AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN humidity >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END AS humidity_tier, COUNT(*) FILTER (WHERE device_code = 'DV-04') AS dv_04_rows, ROUND(AVG(status_bits), 2) AS avg_status_bits FROM sessions_device_readings GROUP BY CASE WHEN humidity >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END;
